.ic-plans{margin-top:var(--s5);border-top:1px solid var(--line)}
.ic-plan{display:grid;grid-template-columns:minmax(0,1fr) 78px 78px 90px;gap:var(--s3);
  align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}
.ic-plan.best{background:var(--ok-bg)}
.ic-plan .pn{font-weight:500;font-size:var(--t-14)}
.ic-plan .pn small{display:block;color:var(--muted);font-weight:400;
  font-family:var(--font-mono);font-size:var(--t-12)}
.ic-plan input{height:38px;padding:0 8px;font-size:16px}
.ic-plan .keep{text-align:right;font-family:var(--font-mono);font-weight:500;
  font-variant-numeric:tabular-nums slashed-zero;font-size:var(--t-14)}
.ic-plan .hd{font-family:var(--font-mono);font-size:var(--t-12);text-transform:uppercase;
  letter-spacing:.08em;color:var(--muted)}
.ic-break{margin-top:var(--s5);border-top:1px solid var(--line)}
.ic-break div{display:flex;justify-content:space-between;gap:var(--s4);
  padding:9px 0;border-bottom:1px solid var(--line);font-size:var(--t-14)}
.ic-break b{font-weight:500;font-variant-numeric:tabular-nums slashed-zero}
@media (max-width:560px){
  .ic-plan{grid-template-columns:minmax(0,1fr) 64px 64px;row-gap:6px}
  .ic-plan .keep{grid-column:1/-1;text-align:left}
}

