(function(){
  var $=function(id){return document.getElementById(id)};
  // Published rates move and differ by country, so these are only starting
  // points. Every one of them is an editable input.
  var DEFAULTS=[
    {name:'Basic',    sub:39,  pct:2.9, fixed:0.30},
    {name:'Grow',     sub:105, pct:2.7, fixed:0.30},
    {name:'Advanced', sub:399, pct:2.5, fixed:0.30}
  ];
  var plans=JSON.parse(JSON.stringify(DEFAULTS));
  function sym(){ return $('sym').value||''; }
  function money(n){ return sym()+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); }

  function build(){
    $('plans').innerHTML=
      '<div class="ic-plan"><span class="hd">Plan and monthly fee</span>'+
      '<span class="hd">% fee</span><span class="hd">Fixed</span><span class="hd keep">Kept / month</span></div>'+
      plans.map(function(p,i){
        return '<div class="ic-plan" data-i="'+i+'">'+
          '<span class="pn">'+p.name+'<small><input type="number" data-f="sub" data-i="'+i+'" value="'+p.sub+'" step="1" min="0" style="width:86px;display:inline-block;margin-top:4px"> per month</small></span>'+
          '<input type="number" data-f="pct" data-i="'+i+'" value="'+p.pct+'" step="0.01" min="0">'+
          '<input type="number" data-f="fixed" data-i="'+i+'" value="'+p.fixed+'" step="0.01" min="0">'+
          '<span class="keep" id="keep'+i+'">none yet</span></div>';
      }).join('');
    $('plans').addEventListener('input',onEdit);
    run();
  }
  function onEdit(e){
    var t=e.target; if(!t.dataset||!t.dataset.f) return;
    plans[+t.dataset.i][t.dataset.f]=+t.value||0;
    run();
  }
  function run(){
    var aov=+$('aov').value||0, orders=+$('orders').value||0, cogs=+$('cogs').value||0;
    var revenue=aov*orders, goods=cogs*orders;
    var results=plans.map(function(p){
      var feePerOrder=aov*p.pct/100 + p.fixed;
      var fees=feePerOrder*orders;
      return { p:p, feePerOrder:feePerOrder, fees:fees,
        keep: revenue - fees - p.sub, profit: revenue - fees - p.sub - goods };
    });
    var best=results.reduce(function(a,b){ return b.keep>a.keep?b:a }, results[0]);
    results.forEach(function(r,i){
      var el=$('keep'+i); if(el) el.textContent=money(r.keep);
      var row=$('plans').querySelector('[data-i="'+i+'"]');
      if(row) row.classList.toggle('best', r===best);
    });
    var b=best;
    $('brk').innerHTML=
      '<div><span>Revenue</span><b>'+money(revenue)+'</b></div>'+
      '<div><span>Payment fees on '+orders+' orders</span><b>-'+money(b.fees)+'</b></div>'+
      '<div><span>Plan subscription</span><b>-'+money(b.p.sub)+'</b></div>'+
      '<div><span>Cost of goods</span><b>-'+money(goods)+'</b></div>'+
      '<div><span>Left after all of that</span><b>'+money(b.profit)+'</b></div>'+
      '<div><span>Fee on a single '+money(aov)+' order</span><b>'+money(b.feePerOrder)+
        ' ('+(aov>0?(b.feePerOrder/aov*100).toFixed(1):'0')+'%)</b></div>';
    // where a dearer plan starts paying for itself
    var msgs=[b.p.name+' keeps the most at this volume.'];
    for(var i=1;i<plans.length;i++){
      var lo=plans[i-1], hi=plans[i];
      var rateGap=(lo.pct-hi.pct)/100;
      if(rateGap>0){
        var breakEven=(hi.sub-lo.sub)/(rateGap*aov);
        if(isFinite(breakEven)&&breakEven>0)
          msgs.push(hi.name+' overtakes '+lo.name+' at about '+Math.ceil(breakEven)+' orders a month at this order value.');
      }
    }
    $('note').textContent=msgs.join(' ');
    if(window.WT) WT.resize();
  }
  ['aov','orders','cogs','sym'].forEach(function(id){$(id).addEventListener('input',run)});
  $('reset').addEventListener('click',function(){
    plans=JSON.parse(JSON.stringify(DEFAULTS));
    $('plans').innerHTML=''; build();
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('brk').textContent.replace(/\s{2,}/g,' ')+' | '+$('note').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy summary'},1400);
  });
  build();
})();
